/// [kPlayTx] metni; {ad} yer tutucuları [p] ile dolar.
String playTx(String key, String lang, [Map<String, Object> p = const {}]) {
  var s = Strings.pick(kPlayTx[key] ?? [key], lang);
  p.forEach((k, v) => s = s.replaceAll('{$k}', '$v'));
  return s;
}
